CREATE TABLE IF NOT EXISTS gis_official_artifacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_key text NOT NULL, filename text NOT NULL, content_type text NOT NULL, storage_key text NOT NULL, sha256 text NOT NULL UNIQUE, byte_size bigint NOT NULL, acquisition_method text NOT NULL, authority_level text NOT NULL DEFAULT 'PRIMARY_OFFICIAL', verification_status text NOT NULL DEFAULT 'RECEIVED', created_by text, created_at timestamptz NOT NULL DEFAULT now());